using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDayAPI.Data;using RaceDayAPI.Models;using System.Security.Claims;namespace RaceDayAPI.Controllers{    [Route("api/[controller]")]    [ApiController]    public class CategoriesController : ControllerBase    {        private readonly RaceDayDbContext _context;        public CategoriesController(RaceDayDbContext context)        {            _context = context;        }        [HttpGet("event/{eventId}")]        [AllowAnonymous]        public async Task<IActionResult> GetCategoriesForEvent(int eventId)        {            var categories = await _context.Categories                .Where(c => c.EventID == eventId)                .ToListAsync();            return Ok(categories);        }        [HttpPost]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> CreateCategory([FromBody] CategoryDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = await _context.Events.FirstOrDefaultAsync(e => e.EventID == dto.EventID);            if (ev == null) return NotFound("Event not found.");            if (ev.OrganiserID != organiser.OrganiserID) return Forbid();            var category = new Category            {                EventID = dto.EventID,                Name = dto.Name,                Distance = dto.Distance,                EntryFee = dto.EntryFee,                StartTime = dto.StartTime,                MaxParticipants = dto.MaxParticipants            };            _context.Categories.Add(category);            await _context.SaveChangesAsync();            return Ok(category);        }        [HttpPut("{id}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> UpdateCategory(int id, [FromBody] CategoryDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var category = await _context.Categories                .Include(c => c.Event)                .FirstOrDefaultAsync(c => c.CategoryID == id);            if (category == null) return NotFound();            if (category.Event.OrganiserID != organiser.OrganiserID) return Forbid();            category.Name = dto.Name ?? category.Name;            if (dto.Distance > 0) category.Distance = dto.Distance;            if (dto.EntryFee > 0) category.EntryFee = dto.EntryFee;            if (dto.StartTime != TimeSpan.Zero) category.StartTime = dto.StartTime;            category.MaxParticipants = dto.MaxParticipants ?? category.MaxParticipants;            await _context.SaveChangesAsync();            return NoContent();        }        [HttpDelete("{id}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> DeleteCategory(int id)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var category = await _context.Categories                .Include(c => c.Event)                .FirstOrDefaultAsync(c => c.CategoryID == id);            if (category == null) return NotFound();            if (category.Event.OrganiserID != organiser.OrganiserID) return Forbid();            _context.Categories.Remove(category);            await _context.SaveChangesAsync();            return NoContent();        }    }    public class CategoryDto    {        public int EventID { get; set; }        public string Name { get; set; } = string.Empty;        public decimal Distance { get; set; }        public decimal EntryFee { get; set; }        public TimeSpan StartTime { get; set; }        public int? MaxParticipants { get; set; }    }}